  "公开文章出现后，这里会按年月自动分组。": "Once public posts appear, this list groups them by year automatically.",
  "新文章发布时通知你，含未发布草稿的片段。": "Notifies you when new posts are published, including fragments of unpublished drafts.",
  "用自然语言提问，AI 会基于全部文章回答。": "Ask in plain language — the AI answers from all the posts.",
  "在控制台把文件加入分享后，这里会出现卡片。": "Share files from the console and cards will appear here.",
  "新主题发布时通过 RSS 第一时间通知你。": "RSS tells you the moment a new topic is published.",
  "发条消息就是一篇文章。AI 自动整理发布。": "One message is one post — the AI drafts and publishes it.",
  "用 RSS 订阅，新文章发出时第一个收到。": "Subscribe via RSS and get new posts first.",
  "在已加载的公开文章内匹配标题、摘要与路径。": "Matches titles, summaries and paths within the loaded public posts.",
  "硬边框、硬阴影、不用渐变。这里只有文章本身。": "Hard borders, hard shadows, no gradients. Only the post itself.",
  "汇聚优质内容，分类整理，助你高效构建知识体系。": "Curated content, organized by category, to help you build a knowledge base.",
  "目录即站点，文件即文章。拖拽即发、语义检索、双链互文。": "Folders are the site, files are the posts. Drag to publish, semantic search, backlinks.",
  "关注互联网及软件 IT 技术的个人博客，记录成长的每一步。": "A personal blog about the internet and software IT, recording every step.",
  "写代码的人，偶尔写点别的。关于技术、设计与生活的个人博客。": "The one who codes, and now and then writes about something else. A personal blog on technology, design and life.",
  "每篇文章可点回原文路径；AI 不替代事实，发布权在站长手里。": "Every post links back to its source path. The AI doesn't replace the facts — publishing stays with the site owner.",
  "拖个文件进目录就是一篇博客。发条 IM 消息，AI 自动整理发布。": "Drop a file into the folder and it's a post. Send an IM message and the AI drafts it.",
  "全文 + 语义检索，把碎片知识拼成可导航的公开站，而不是一堆附件。": "Full-text + semantic search turning scattered notes into a navigable public site instead of a pile of attachments.",
  "在知识库「博客」目录放入 Markdown 并发布后，这里会自动出现。": "Put Markdown in the 「Blog」 folder and publish — posts show up here automatically.",
  "拖进博客目录即发布；slug 不碎链；RSS / sitemap 一并就绪。": "Drop it in the blog folder to publish; slugs never break links; RSS / sitemap included.",
  "当前列表数据未包含作者字段，以下为全部公开文章；系统补齐后本页会自动按作者过滤。": "The current data has no author field, so all public posts are listed. Once the system exposes it, this page filters by author automatically.",
  "知识不在聊天记录里，在可发布的目录里。一份 Markdown，就是一个可检索节点。": "Knowledge isn't in chat logs, it's in publishable folders. One Markdown file is one searchable node.",
  "在标题、摘要与文件路径中做不区分大小写的匹配，结果保持系统排序（置顶优先 + 时间倒序）。": "Case-insensitive match across titles, summaries and file paths, keeping the system order (pinned first, then newest).",
  "本博客所有文章除特别声明外，均采用「署名 - 非商业性使用 - 相同方式共享」许可协议。转载请注明出处。": "Unless stated otherwise, all posts use CC BY-NC-SA. Please credit the original source when reposting.",
