  "聚合你的文件、标签、摘要与关系 —— 概念、图谱、集合在此汇流": "Your files, tags, summaries and relations converge here — concepts, graph and collections",
  "质量检查只读不改数据 · 断链基于已索引内容匹配文件名（全名/去扩展名）": "Quality checks are read-only · broken links match indexed file names (full or without extension)",
  "还没有标签。在文件库中对文件打标签，这里会自动聚合。": "No tags yet. Tag files in the file library and they aggregate here automatically.",
  "还没有集合。手动收藏重要文件，或用标签/关键词建一个智能集合。": "No collections yet. Bookmark important files, or build a smart collection from tags/keywords.",
  "还没有集合，去「集合」tab 建一个": "No collections yet; create one on the \"Collections\" tab",
  "重复文件（sha256 相同）": "Duplicate files (same sha256)",
  "集合（手动收藏 / 智能筛选）": "Collections (manual bookmarks / smart filters)",
  "项）": ")",
  "一套自部署系统，覆盖从内容沉淀、AI 整理到对外分发的完整闭环。": "A self-hosted system covering the full loop from capturing content and AI organizing to public publishing.",
  "主题与插件的在线市场。外观换肤、功能增强都能像安装应用一样完成，按站点需要分发与解锁。": "An online marketplace for themes and plugins. Restyle or extend as easily as installing an app, distributed and unlocked per site.",
  "你的内容、你的服务器。不绑定任何平台，不担心停服与数据出走，完全掌控自己的知识资产与访问规则。": "Your content, your server. No platform lock-in, no fear of shutdown or data exodus — full control over your knowledge assets and access rules.",
  "内置一组 AI 工具——智能探路建源、网页剪藏、内容组织与打标等，由统一能力开关门控，可按站点按需启用。": "Built-in AI tools — smart source discovery, web clipping, content organizing and tagging — gated by unified capability switches and enabled per site.",
  "写文件即发文，AI 辅助整理、摘要与发布。同一份内容，对内是知识库，对外是博客，不必维护两套。": "Writing a file is publishing. AI helps organize, summarize and publish. One copy serves as both internal knowledge base and public blog — no duplicate upkeep.",
  "博客主题支持服务端渲染免编译热投放——换肤、调版式不必重新构建发布，上传即用、即时生效。": "Blog themes support server-side rendering with hot delivery and no rebuild — restyle or change the layout without rebuilding; upload and it takes effect instantly.",
  "双轨渲染 · SEO 友好": "Dual-track rendering · SEO friendly",
  "同一 URL，爬虫看到服务端渲染的纯 HTML，读者看到交互式单页应用。搜索引擎收录与读者体验兼得。": "At the same URL, crawlers get server-rendered HTML while readers get an interactive SPA. Search indexing and reader experience, both.",
  "同一套自部署实例承载多个相互独立的站点 / 租户：内容、分类、主题与站点设置按站点隔离。自定义域名、子域名或子目录三种接入方式任选，矩阵站群一站管控。": "One self-hosted instance hosts multiple independent sites/tenants: content, categories, themes and settings are isolated per site. Choose a custom domain, subdomain or subdirectory — manage the whole site matrix in one place.",
  "录": "log",
  "爱库录 AiKlog · 自部署 AI 知识库博客系统": "AiKlog · self-hosted AI knowledge base blog system",
  "目录即站点，文件即文章。一套系统，把你的笔记、文档与文章变成可被搜索、可被分享、可被 AI 理解的知识库与博客——内容与服务都运行在你自己的服务器上。": "Folders are sites, files are articles. One system turns your notes, documents and articles into a searchable, shareable, AI-readable knowledge base and blog — running on your own server.",
  "系统自带注册与登录，邮箱验证码 + IP 限流开箱可用。一个实例即可服务多个真实用户，不必外接身份系统。": "Built-in sign-up and sign-in with email codes + IP rate limiting out of the box. One instance serves many real users with no external identity system.",
  "组织树、部门空间、成员任职与文件移交流转一应俱全。内容按组织节点聚合与授权，适合团队共同维护知识库。": "Org tree, department spaces, member roles and file handover workflows included. Content aggregates and authorizes by org node — ideal for teams maintaining a knowledge base together.",
  "自部署 AI 知识库博客系统": "Self-hosted AI knowledge base blog system",
  " 天前": " days ago",
  "也能识别（按用户名/显示名反查）。": " are also recognized (looked up by username/display name).",
  "把文章分享给别人，或在评论区互相 @ 一下试试。": "Share an article, or @ each other in the comments to try it out.",
  "是精确写法， 直接写": " is the exact form; simply write",
  "有人": "Someone",
  "评论或文章里 @ 到你的时候会落在这里。写": "Mentions of you in comments or articles land here. Write",
  "不勾选具体资产时，预演会按「我作为责任人的全部文件」生成清单。": "With no assets selected, the dry run lists all files you are responsible for.",
  "人 ·": " people · ",
  "人（岗位变更唯一入口，写岗位历史）": " people (the only entry point for role changes; writes role history)",
  "企业知识库的组织维度：组织树给内容打标、岗位快照记录成员归属、移交流负责人员变动时的资产交接。 子开关由服务端配置（": "The organizational dimension of the enterprise knowledge base: the org tree tags content, role snapshots record member affiliation, and handover handles asset transfer on staff changes. Child switches are configured server-side (",
  "加成员（部门级授权，不写岗位历史）": "Add member (department-level grant, no role history)",
  "在任": "Active",
  "挂岗": "Assign role",
  "挂岗会关闭该成员在同一节点的历史岗位并新增一条记录，用于资产归属追溯。": "Assigning a role closes the member previous role at the same node and adds a new record for asset attribution.",
  "模块未启用时下列端点返回 403/404，属预期（能力未开启）。": "When the module is off, these endpoints return 403/404 as expected (capability not enabled).",
  "流程：发起(draft) → 预演 → 执行 → 接收人确认(accepted/归档) → 取消可随时中止。": "Flow: create (draft) → dry run → execute → recipient confirms (accepted/archived) → cancel at any time.",
