  "清理是安全的：派生对象不是用户文件，删掉只会让缩略图在下次访问时重新生成（首次略慢）。 「孤儿」= 源文件已不存在的派生对象（直接改库、回滚数据库备份会留下这类残留），可与缓存一并清掉。 这里设的「自动清理间隔」会让服务定时兜底清孤儿（默认每天一次）；「立即清理孤儿」可随时手动触发一次。": "Cleaning is safe: derived objects are not user files; deleting them only makes thumbnails regenerate on next access (slightly slower the first time). \"Orphans\" are derived objects whose source file no longer exists (direct DB edits or DB restores leave them behind) and can be cleared with the cache. The \"auto-clean interval\" here lets the service clean orphans periodically (once a day by default); \"Clean orphans now\" triggers it manually at any time.",
  "清空全部派生对象（缩略图缓存）？ 这不影响任何用户文件，只是让缩略图在下次访问时按当前参数重新生成。": "Clear all derived objects (thumbnail cache)? This does not affect any user file; thumbnails regenerate with the current settings on next access.",
