  "如 blog.example.com": "e.g. blog.example.com",
  "如 docs / shop（唯一，不含空格）": "e.g. docs / shop (unique, no spaces)",
  "子域名 ": "Subdomain ",
  "子目录 ": "Subdirectory ",
  "接入方式三选一即可：自定义域名 / 子域名 / 子目录。三者都不填时该站仅通过后台预览。": "Choose one access method: custom domain / subdomain / subdirectory. With none set, the site is preview-only in the admin.",
  "显示在页头 / SEO 的站点名": "Site name shown in the header / SEO",
  "暂无授权（基础免费档 1 个站点）": "No license yet (free tier: 1 site)",
  "校验中…": "Verifying…",
  "每张授权含可用站点数；订阅到期后额度自动回落。": "Each license includes a site allowance; the quota falls back automatically when the subscription expires.",
  "永久": "Perpetual",
  "生效": "Active",
  "站点数已达上限，请先录入授权": "Site limit reached; add a license first",
  "粘贴在应用中心购买的授权 key（含": "Paste the license key purchased in the app center (includes",
  "至 ": " to ",
  "仅显示生效中的授权（已吊销 / 已过期不列出）": "Shows only active licenses (revoked / expired are hidden)",
  "到期 ": "Expires ",
  "可授权的能力资产（tool / skill / workflow / extension）。管理员上架后在此目录可见； 免费包可自助领取，付费包由管理员发放授权。 与应用中心（主题 / 插件 / 站点授权）是两条线：那条管站点能力，这条管能力资产。": "Licensable capability assets (tool / skill / workflow / extension). Visible in this catalog after an admin publishes them; free packs can be claimed, paid packs are granted by an admin. Separate from the app center (themes / plugins / site licenses): that one covers site capabilities, this one covers capability assets.",
  "管理员可通过接口上架（POST /api/v1/admin/skills，status=published 后可见）。": "Admins can publish via the API (POST /api/v1/admin/skills; visible once status=published).",
  "在上方新建一个顶层标签；右键文件 →「标签/分类」→ 可新建子标签": "Create a top-level tag above; right-click a file → \"Tags/Categories\" → create a sub-tag",
  "查看该标签下的文件，或进行 子标签 / 重命名 / 删除 操作": "View files under this tag, or manage sub-tags / rename / delete",
  "统一树状标签 = 文件分类 / 知识库概念 / 博客分类 的同一套体系": "One unified tag tree = the same system for file categories, KB concepts and blog categories",
  "该标签下暂无文件 —— 在文件库选中文件 →「标签/分类」打上这个标签": "No files under this tag yet — select files in the file library → \"Tags/Categories\" to tag them",
  "删除的文件会先到这里，可以恢复；彻底删除后无法找回": "Deleted files land here first and can be restored; permanent deletion is irreversible",
  "已删除的内容暂存于此；恢复回到原位置，彻底删除不可恢复": "Deleted content is held here; restoring returns it to its original place, permanent deletion is unrecoverable",
  "owner 账号不可修改": "The owner account cannot be modified",
  "新用户通过公开注册入口自行注册（受「开放注册」开关与邮箱验证码约束），注册后默认角色为 member。": "New users self-register via the public entry (subject to the \"open registration\" switch and email codes); the default role is member.",
  "站点成员的角色与状态。owner 账号受保护（不可降级/禁用，避免把系统锁死）； 角色决定后台可见范围，状态决定能否登录。": "Roles and status of site members. The owner account is protected (cannot be demoted/disabled, to avoid locking the system); roles decide admin visibility, status decides whether sign-in is allowed.",
  "地址需为 WebDAV 根（以 / 结尾更稳）；凭据服务端加密存储，前端不再回显明文密码。": "The address must be the WebDAV root (ending with / is safer); credentials are encrypted server-side and never echoed in plain text.",
  "导入中…": "Importing…",
  "导入当前目录（递归第一层）": "Import the current folder (first level, recursive)",
  "把远端 WebDAV 服务挂进来浏览，并把文件导入知识库（目录导入取递归第一层文件）。 本机也可被外部挂载：服务端提供": "Mount a remote WebDAV service to browse and import files into the knowledge base (folder import takes the first level recursively). This machine can also be mounted externally: the server provides",
  "编辑挂载": "Edit mount",
  "（留空不改）": "(leave empty to keep)",
  "https://… 或站内可公开访问的图片地址（留空不设）": "https://… or a publicly reachable image URL on this site (empty = none)",
  "上传封面": "Upload cover",
  "保存文章时一并保存本面板；SEO 字段用于 SSR 页 title/description/OG，缺省自动回退。": "This panel is saved together with the article; SEO fields feed the SSR page title/description/OG and fall back automatically when empty.",
  "在「提示词模板」页新建 / 编辑模板": "Create / edit templates on the \"Prompt templates\" page",
  "基于标题与知识库素材生成大纲": "Generate an outline from the title and knowledge-base material",
  "封面图 / 摘要 / SEO": "Cover / summary / SEO",
  "已收录记录（最近 20 条）": "Inclusion log (latest 20)",
  "已替换正文（原内容可用浏览器撤销 Ctrl+Z 找回）": "Body replaced (undo with Ctrl+Z in the browser to recover the original)",
  "未解析的变量（已原样保留）：": "Unresolved variables (kept as-is): ",
  "本文章暂无已通过评论可收录。": "This article has no approved comments to include yet.",
  "正文已保存，但封面/SEO 保存失败：": "The body was saved, but the cover/SEO save failed: ",
  "用可配置的提示词模板生成（变量填值即用）": "Generate with a configurable prompt template (fill in variables and go)",
  "留空则用摘要（搜索引擎结果页描述）": "Empty falls back to the summary (search result description)",
  "留空则自动取正文开头 / AI 摘要": "Empty auto-takes the body opening / AI summary",
  "素材检索：输入关键词，从本站知识库找素材（回车检索）": "Material search: type keywords to find material in this site knowledge base (Enter to search)",
  "补充细节，篇幅 1.5-2 倍": "Add detail, 1.5–2× longer",
  "访客": "Visitor",
  "该模板没有变量，直接点「用模板生成」即可。": "This template has no variables; just click \"Generate with template\".",
  "请先填写文章标题（作为大纲主题）": "Please enter the article title first (used as the outline topic)",
  "还没有提示词模板。去「提示词模板」页新建一个，即写即用。": "No prompt templates yet. Create one on the \"Prompt templates\" page — write and use immediately.",
  "作者数据尚未由系统侧透出，敬请期待": "Author data is not yet exposed by the system — stay tuned",
  "作者数据尚未由系统侧透出（规范 §10-10），敬请期待": "Author data is not yet exposed by the system (spec §10-10) — stay tuned",
  "提问太频繁了，请稍等几分钟再试。": "You are asking too frequently; please wait a few minutes and try again.",
