  "未绑定接入方式": "No access method bound",
  "访客默认看到该主题；访客可用页头切换器换成自己习惯的主题（仅本机记住，不影响其他访客）。仅作用于交互版公开页；静态页 /blog 固定阅读壳（SEO）。外置主题部署到服务器 data/themes/<id>/ 即自动出现在本下拉，无需改白名单或重编译": "Visitors see this theme by default; they can switch to one they prefer with the header switcher (remembered locally only, no effect on others). Applies to the interactive public pages only; the static /blog page uses a fixed reading shell (SEO). An external theme deployed to data/themes/<id>/ on the server appears in this dropdown automatically — no whitelist edit or rebuild needed",
  "内核模块的启用判定：站长配置 > 应用中心已装应用记录 > 内置默认开启。关闭后对应端点下线（404 = 能力未启用），数据保留。多数模块在进程启动阶段装配，改动": "Enablement of core modules: site-owner config > app-center installed record > built-in default on. When off, the related endpoints go offline (404 = capability not enabled) and data is kept. Most modules are wired at process startup, so changes ",
  "键：": "Key: ",
  "spaces/<空间>/.derived/<文件>/": "spaces/<space>/.derived/<file>/",
  "当前博客数据契约未包含文章作者字段，因此无法按作者筛选。下方展示站点全部文章，待系统透出": "The current blog data contract does not include the article author field, so filtering by author is unavailable. All site articles are shown below; once the system exposes",
  "删除标签「{v0}」？它名下没有文件，删除不影响任何内容。": "Delete tag \"{v0}\"? It contains no files, so deleting it does not affect any content.",
  "删除集合「{v0}」？集合内文件不会被删除。": "Delete collection \"{v0}\"? Files inside the collection will not be deleted.",
  "删除节点「{v0}」？若节点仍有成员或挂载文件，服务端会拒绝。": "Delete node \"{v0}\"? The server will reject it if the node still has members or mounted files.",
  "删除「{v0}」？文章将从博客下线（可在回收站恢复）。": "Delete \"{v0}\"? The post will be unpublished from the blog (restorable from trash).",
  "删除站点「{v0}」？站点将停用并从列表移除，已有内容数据保留。": "Delete site \"{v0}\"? It will be disabled and removed from the list; existing content is kept.",
  "删除标签「{v0}」？其下所有子标签一并删除，文件本身不受影响。": "Delete tag \"{v0}\"? All of its child tags will be removed too; the files themselves are unaffected.",

